#include <iostream>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int a, ta;
    int b, tb;
    string time_str;

    cin >> a >> ta;
    cin >> b >> tb;
    cin >> time_str;

    // Parse departure time
    int h = stoi(time_str.substr(0, 2));
    int m = stoi(time_str.substr(3, 2));

    // Time in minutes since 00:00
    int simion_depart = h * 60 + m;
    int simion_arrive = simion_depart + ta;

    int count = 0;

    // Buses from B depart every b minutes starting from 05:00 (300 minutes).
    // Last departure from B is not later than 23:59 (1439 minutes).
    // A bus departing B at time T_depart_B is on the road during [T_depart_B, T_depart_B + tb].
    // Simion is on the road during [simion_depart, simion_arrive].
    // They meet on the road (not at cities) if intervals overlap strictly:
    // T_depart_B < simion_arrive AND T_depart_B + tb > simion_depart.

    for (int t_b = 300; t_b <= 1439; t_b += b) {
        if (t_b < simion_arrive && t_b + tb > simion_depart) {
            count++;
        }
    }

    cout << count << endl;

    return 0;
}
